scripts.claude:
#!/bin/sh
cd /Users/a/godspeed || exit 1
command -v claude >/dev/null 2>&1 || { echo "Claude Code isn't installed. Get it at https://claude.com/claude-code, then click Start again in godspeed."; exit 3; }
command -v node >/dev/null 2>&1 || { echo "godspeed needs Node.js. Install it from https://nodejs.org, then click Start again in godspeed."; exit 4; }
exec claude --settings .godspeed/claude-settings.json "Start teaching"

