scripts.codex:
#!/bin/sh
cd /Users/a/godspeed || exit 1
command -v codex >/dev/null 2>&1 || { echo "Codex isn't installed. Get it at https://developers.openai.com/codex, then click Start again in godspeed."; exit 3; }
